/**
 * Prediction endpoint — mirrors POST /predict of the FastAPI backend.
 *
 * The machine-learning inference runs server-side: the trained Random Forest
 * artifact (generated by ml/train_model.ts) is loaded by this action, input is
 * validated and encoded into the model's feature vector, and the ensemble
 * produces the class probabilities. The browser never computes predictions.
 *
 * Request:  { symptoms: ["fever", "cough", ...] }
 * Response: {
 *   predicted_disease: string,
 *   confidence: number,            // fraction of ensemble trees for the top class
 *   selected_symptoms: string[],
 *   top_predictions: [{ disease, confidence }]  // top 3
 *   timestamp: string
 * }
 */

import { action } from "./_generated/server";
import { ConvexError, v } from "convex/values";
import {
  buildPrediction,
  PredictionValidationError,
  validateSymptoms,
} from "./ml/inference";
import { MODEL } from "./ml_model";

export const predict = action({
  args: { symptoms: v.array(v.string()) },
  handler: async (_ctx, args) => {
    let normalized: string[];
    try {
      normalized = validateSymptoms(args.symptoms);
    } catch (err) {
      if (err instanceof PredictionValidationError) {
        throw new ConvexError({ code: "invalid_symptoms", message: err.message });
      }
      throw err;
    }
    return buildPrediction(MODEL, normalized);
  },
});
